class Policy:
    # Changed: prioritize near-solved tasks (score >= 0.8) over lowest scores, and use UCB-style exploration for untried tasks
    def __init__(self):
        self.scores = {}  # task_id -> best score seen
        self.attempts = {}  # task_id -> number of times picked

    def pick(self, keys, round_index):
        # First, prefer tasks we haven't tried yet (unknown score)
        untried = [k for k in keys if k not in self.scores]
        if untried:
            # Among untried, use round-robin to spread exploration
            return untried[round_index % len(untried)]

        # All tasks have been tried; prefer unsolved ones (score < 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if unsolved:
            # Among unsolved, prioritize tasks with high scores (close to solved)
            # but not yet solved - these are most likely to be pushed over the edge
            near_solved = [k for k in unsolved if self.scores[k] >= 0.8]
            if near_solved:
                # Among near-solved, pick the one with highest score (closest to 1.0)
                return max(near_solved, key=lambda k: self.scores[k])
