class Policy:
    # Changed: prioritize low-score tasks with uncertainty, avoid solved tasks entirely, and use round-aware exploration
    def __init__(self):
        self.scores = {}  # task_id -> best score seen
        self.attempts = {}  # task_id -> number of times picked

    def pick(self, keys, round_index):
        # Filter to only unsolved tasks (score < 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]

        if unsolved:
            # Separate into untried and tried-but-unsolved
            untried = [k for k in unsolved if k not in self.scores]
            tried = [k for k in unsolved if k in self.scores]

            if untried:
                # Early rounds: explore untried tasks, but later rounds focus on improving known ones
                # Use round_index to shift from exploration to exploitation
                if round_index < 4 and len(untried) > 1:
                    # Early: spread exploration among untried
                    return untried[round_index % len(untried)]
                else:
                    # Later: try untried tasks that might be easy wins
                    return untried[0]

            if tried:
                # Among tried unsolved, pick the one with lowest score (most room for improvement)
                # Break ties by fewest attempts (less explored)
                return min(tried, key=lambda k: (self.scores[k], self.attempts.get(k, 0)))

        # If all solved or no unsolved, pick from keys but avoid solved if possible
        # This fallback rarely happens but ensures protocol compliance
        return keys[round_index % len(keys)]

    def record(self, task_id, score):
        # Keep the best score seen for each task
        if task_id not in self.scores or score > self.scores[task_id]:
            self.scores[task_id] = score
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
